from pathlib import Path

PY_PATH = Path('scripts/update_stock_meta.py')
JS_PATH = Path('assets/js/quant-main-display.js')

py = PY_PATH.read_text(encoding='utf-8')
js = JS_PATH.read_text(encoding='utf-8')


def replace_once(text: str, old: str, new: str, label: str) -> str:
    count = text.count(old)
    if count != 1:
        raise SystemExit(f'{label}: expected 1 match, found {count}')
    return text.replace(old, new, 1)


py = replace_once(
    py,
    '''def score_trend(m1, m3, m6, m12, ma60, ma200) -> float:\n    score = 5.0\n    for val, weight in [(m1, 10.0), (m3, 8.0), (m6, 5.0), (m12, 3.5), (ma60, 7.0), (ma200, 5.0)]:\n        if val is not None:\n            score += max(-1.6, min(1.6, val * weight))\n    return clamp(score)\n''',
    '''def score_trend(ma20_gap, ma60_gap, ma200_gap, ma20_slope, ma60_slope, ma200_slope) -> float:\n    \"\"\"0-10 structural trend score based only on moving-average state and slope.\"\"\"\n    score = 5.0\n    parts = [\n        (ma20_gap, 12.0, 0.9),\n        (ma60_gap, 9.0, 1.0),\n        (ma200_gap, 6.0, 1.1),\n        (ma20_slope, 14.0, 0.7),\n        (ma60_slope, 12.0, 0.7),\n        (ma200_slope, 10.0, 0.6),\n    ]\n    for val, weight, cap_value in parts:\n        value = finite_float(val)\n        if value is not None:\n            score += max(-cap_value, min(cap_value, value * weight))\n    return clamp(score)\n\n\ndef score_momentum(m1, m3, m6, m12) -> float:\n    \"\"\"0-10 absolute-price momentum score; recent horizons receive more weight.\"\"\"\n    score = 5.0\n    parts = [\n        (m1, 10.0, 1.0),\n        (m3, 7.0, 1.4),\n        (m6, 4.5, 1.4),\n        (m12, 2.5, 1.2),\n    ]\n    for val, weight, cap_value in parts:\n        value = finite_float(val)\n        if value is not None:\n            score += max(-cap_value, min(cap_value, value * weight))\n    return clamp(score)\n''',
    'split trend and momentum scoring',
)

py = replace_once(
    py,
    '''    ma20, ma60, ma200 = safe_last(close.rolling(20).mean()), safe_last(close.rolling(60).mean()), safe_last(close.rolling(200).mean())\n    ma20_gap, ma60_gap, ma200_gap = pct(last_price, ma20), pct(last_price, ma60), pct(last_price, ma200)\n''',
    '''    ma20_series = close.rolling(20).mean()\n    ma60_series = close.rolling(60).mean()\n    ma200_series = close.rolling(200).mean()\n    ma20, ma60, ma200 = safe_last(ma20_series), safe_last(ma60_series), safe_last(ma200_series)\n    ma20_gap, ma60_gap, ma200_gap = pct(last_price, ma20), pct(last_price, ma60), pct(last_price, ma200)\n    ma20_slope_20d = pct(ma20, safe_last(ma20_series.shift(20)))\n    ma60_slope_20d = pct(ma60, safe_last(ma60_series.shift(20)))\n    ma200_slope_20d = pct(ma200, safe_last(ma200_series.shift(20)))\n''',
    'moving-average slope features',
)

py = replace_once(
    py,
    '''    trend = score_trend(mom1, mom3, mom6, mom12, ma60_gap, ma200_gap)\n    risk_s = score_risk(vol60, vol252, mdd_1y, beta, corr)\n''',
    '''    trend = score_trend(ma20_gap, ma60_gap, ma200_gap, ma20_slope_20d, ma60_slope_20d, ma200_slope_20d)\n    momentum = score_momentum(mom1, mom3, mom6, mom12)\n    risk_s = score_risk(vol60, vol252, mdd_1y, beta, corr)\n''',
    'compute independent factor scores',
)

py = replace_once(
    py,
    '''    quant_health = clamp(0.30 * trend + 0.20 * tech + 0.15 * (chip if chip is not None else 5.0) + 0.15 * valuation + 0.20 * (10.0 - risk_s))\n''',
    '''    quant_health = clamp(0.15 * trend + 0.15 * momentum + 0.20 * tech + 0.15 * (chip if chip is not None else 5.0) + 0.15 * valuation + 0.20 * (10.0 - risk_s))\n''',
    'health factor de-duplication',
)

py = replace_once(
    py,
    '''        \"ma200_gap\": round(ma200_gap, 6) if ma200_gap is not None else None,\n        \"max_drawdown_1y\": round(mdd_1y, 6) if mdd_1y is not None else None,\n        \"trend_score\": trend,\n        \"momentum_score\": trend,\n''',
    '''        \"ma200_gap\": round(ma200_gap, 6) if ma200_gap is not None else None,\n        \"ma20_slope_20d\": round(ma20_slope_20d, 6) if ma20_slope_20d is not None else None,\n        \"ma60_slope_20d\": round(ma60_slope_20d, 6) if ma60_slope_20d is not None else None,\n        \"ma200_slope_20d\": round(ma200_slope_20d, 6) if ma200_slope_20d is not None else None,\n        \"max_drawdown_1y\": round(mdd_1y, 6) if mdd_1y is not None else None,\n        \"trend_score\": trend,\n        \"momentum_score\": momentum,\n''',
    'persist split factor metrics',
)

js = replace_once(
    js,
    '''      #${Q_PANEL_ID} .qwrap{overflow-x:auto}#${Q_PANEL_ID} table{width:max-content;min-width:100%;border-collapse:collapse;font-size:12px}#${Q_PANEL_ID} th,#${Q_PANEL_ID} td{padding:10px;border-bottom:1px solid rgba(255,255,255,.07);text-align:right;white-space:nowrap}#${Q_PANEL_ID} th{color:#94a3b8;font-size:10px;text-transform:uppercase;letter-spacing:.08em;background:rgba(15,23,42,.96)}#${Q_PANEL_ID} th:first-child,#${Q_PANEL_ID} td:first-child{text-align:left;position:sticky;left:0;background:rgba(15,23,42,.98);z-index:2}.badge{display:inline-flex;min-width:42px;justify-content:center;border-radius:999px;border:1px solid rgba(255,255,255,.10);padding:3px 7px;background:rgba(255,255,255,.04);font-weight:800}.ticker{font-weight:900;color:#fff}.qmi-small{display:block;color:#94a3b8;font-size:10px;margin-top:4px;max-width:220px;white-space:normal;line-height:1.35;text-align:right}\n      details.qmi-details>summary{cursor:pointer;color:#93c5fd;font-weight:900;margin-bottom:8px}\n      @media(max-width:1000px){.qmi-grid,.qmi-grid6{grid-template-columns:repeat(2,minmax(0,1fr))}.qmi-head{flex-direction:column}.qmi-meta{text-align:left}}\n''',
    '''      #${Q_PANEL_ID} .qwrap{overflow-x:auto}#${Q_PANEL_ID} table{width:max-content;min-width:100%;border-collapse:collapse;font-size:12px}#${Q_PANEL_ID} th,#${Q_PANEL_ID} td{padding:10px;border-bottom:1px solid rgba(255,255,255,.07);text-align:right;white-space:nowrap}#${Q_PANEL_ID} th{color:#94a3b8;font-size:10px;text-transform:uppercase;letter-spacing:.08em;background:rgba(15,23,42,.96)}#${Q_PANEL_ID} th:first-child,#${Q_PANEL_ID} td:first-child{text-align:left;position:sticky;left:0;background:rgba(15,23,42,.98);z-index:2}.badge{display:inline-flex;min-width:42px;justify-content:center;border-radius:999px;border:1px solid rgba(255,255,255,.10);padding:3px 7px;background:rgba(255,255,255,.04);font-weight:800}.ticker{font-weight:900;color:#fff}.qmi-small{display:block;color:#94a3b8;font-size:10px;margin-top:4px;max-width:220px;white-space:normal;line-height:1.35;text-align:right}\n      #${Q_PANEL_ID} .qcards{display:none}.q-mobile-card{border-top:1px solid rgba(255,255,255,.08);padding:14px 14px 15px;background:rgba(2,6,23,.22)}.q-mobile-card:first-child{border-top:0}.q-mobile-top{display:flex;align-items:center;justify-content:space-between;gap:10px}.q-mobile-top-right{display:flex;align-items:center;gap:8px;flex-wrap:wrap;justify-content:flex-end}.q-quality{font:10px ui-monospace,SFMono-Regular,Menlo,monospace;color:#94a3b8}.q-factor-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;margin-top:12px}.q-factor{border:1px solid rgba(255,255,255,.08);background:rgba(255,255,255,.025);border-radius:10px;padding:8px 6px;text-align:center;min-width:0}.q-factor-k{font-size:9px;color:#94a3b8;font-weight:800}.q-factor-v{margin-top:4px;font:700 13px ui-monospace,SFMono-Regular,Menlo,monospace}.q-zone-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin-top:10px}.q-zone{border-radius:10px;background:rgba(255,255,255,.025);padding:8px 10px}.q-zone-k{color:#94a3b8;font-size:9px;font-weight:800}.q-zone-v{margin-top:4px;font:11px ui-monospace,SFMono-Regular,Menlo,monospace;line-height:1.45}.q-position{margin-top:10px;color:#cbd5e1;font-size:11px;line-height:1.55}.q-mobile-foot{margin-top:8px;color:#64748b;font:9px ui-monospace,SFMono-Regular,Menlo,monospace;line-height:1.45;overflow-wrap:anywhere}\n      details.qmi-details>summary{cursor:pointer;color:#93c5fd;font-weight:900;margin-bottom:8px}\n      @media(max-width:1000px){.qmi-grid,.qmi-grid6{grid-template-columns:repeat(2,minmax(0,1fr))}.qmi-head{flex-direction:column}.qmi-meta{text-align:left}}\n      @media(max-width:700px){#${Q_PANEL_ID} .qwrap{display:none}#${Q_PANEL_ID} .qcards{display:block}#${Q_PANEL_ID} .qmi-head{padding:14px}.q-factor-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.qmi-sub{font-size:10px}.qmi-meta{font-size:9px}}\n''',
    'mobile quant card styles',
)

old_rows = '''    const rows = list.map((t) => {\n      const x = meta[t] || {};\n      const position = x.pivot_position_plain || x.pivot_status || \"N/A\";\n      const signal = x.pivot_signal || \"N/A\";\n      const reason = x.pivot_signal_reason || \"\";\n      return `<tr><td><span class=\"ticker\">${esc(t)}</span></td><td>${n(x.beta,2)}</td><td><span class=\"badge ${scoreClass(x.trend_score)}\">${n(x.trend_score,2)}</span></td><td><span class=\"badge ${scoreClass(x.momentum_score)}\">${n(x.momentum_score,2)}</span></td><td><span class=\"badge ${scoreClass(x.risk_score,true)}\">${n(x.risk_score,2)}</span></td><td>${n(x.technical_score,2)}</td><td>${n(x.valuation_score,2)}</td><td><span class=\"badge ${scoreClass(x.quant_health_score)}\">${n(x.quant_health_score,2)}</span></td><td>${zone(x,\"support\")}</td><td>${zone(x,\"resistance\")}</td><td>${esc(position)}</td><td><span class=\"badge ${signalClass(signal)}\">${esc(signal)}</span>${reason ? `<span class=\"qmi-small\">${esc(reason)}</span>` : \"\"}</td><td>${esc(x.data_quality || \"N/A\")}</td><td>${esc(x.source || \"N/A\")}</td><td>${esc(x.updated_at || \"N/A\")}</td></tr>`;\n    }).join(\"\");\n    p.innerHTML = `<div class=\"qmi-head\"><div><div class=\"qmi-title\">量化因子總覽</div><div class=\"qmi-sub\">庫存頁只放單檔資料：Beta、趨勢、動能、風險、健康度與月線支撐/壓力；籌碼保留為台股附加資料，不納入跨資產核心 Factor。</div></div><div class=\"qmi-meta\">持倉數=${list.length}<br>最新=${esc(latest)}</div></div><div class=\"qwrap\"><table><thead><tr><th>代號</th><th>Beta</th><th>趨勢</th><th>動能</th><th>風險</th><th>技術</th><th>估值</th><th>健康度</th><th>月支撐</th><th>月壓力</th><th>月線位置</th><th>綜合訊號</th><th>品質</th><th>來源</th><th>更新</th></tr></thead><tbody>${rows}</tbody></table></div>`;\n'''

new_rows = '''    const rows = list.map((t) => {\n      const x = meta[t] || {};\n      const position = x.pivot_position_plain || x.pivot_status || \"N/A\";\n      const signal = x.pivot_signal || \"N/A\";\n      const reason = x.pivot_signal_reason || \"\";\n      return `<tr><td><span class=\"ticker\">${esc(t)}</span></td><td>${n(x.beta,2)}</td><td><span class=\"badge ${scoreClass(x.trend_score)}\">${n(x.trend_score,2)}</span></td><td><span class=\"badge ${scoreClass(x.momentum_score)}\">${n(x.momentum_score,2)}</span></td><td><span class=\"badge ${scoreClass(x.risk_score,true)}\">${n(x.risk_score,2)}</span></td><td>${n(x.technical_score,2)}</td><td>${n(x.valuation_score,2)}</td><td><span class=\"badge ${scoreClass(x.quant_health_score)}\">${n(x.quant_health_score,2)}</span></td><td>${zone(x,\"support\")}</td><td>${zone(x,\"resistance\")}</td><td>${esc(position)}</td><td><span class=\"badge ${signalClass(signal)}\">${esc(signal)}</span>${reason ? `<span class=\"qmi-small\">${esc(reason)}</span>` : \"\"}</td><td>${esc(x.data_quality || \"N/A\")}</td><td>${esc(x.source || \"N/A\")}</td><td>${esc(x.updated_at || \"N/A\")}</td></tr>`;\n    }).join(\"\");\n    const cards = list.map((t) => {\n      const x = meta[t] || {};\n      const position = x.pivot_position_plain || x.pivot_status || \"N/A\";\n      const signal = x.pivot_signal || \"N/A\";\n      const reason = x.pivot_signal_reason || \"\";\n      const factor = (label, value, cls = \"\") => `<div class=\"q-factor\"><div class=\"q-factor-k\">${esc(label)}</div><div class=\"q-factor-v ${cls}\">${esc(value)}</div></div>`;\n      return `<article class=\"q-mobile-card\"><div class=\"q-mobile-top\"><span class=\"ticker\">${esc(t)}</span><div class=\"q-mobile-top-right\"><span class=\"badge ${signalClass(signal)}\">${esc(signal)}</span><span class=\"q-quality\">${esc(x.data_quality || \"N/A\")}</span></div></div><div class=\"q-factor-grid\">${factor(\"Beta\", n(x.beta,2))}${factor(\"趨勢\", n(x.trend_score,2), scoreClass(x.trend_score))}${factor(\"動能\", n(x.momentum_score,2), scoreClass(x.momentum_score))}${factor(\"風險\", n(x.risk_score,2), scoreClass(x.risk_score,true))}${factor(\"健康度\", n(x.quant_health_score,2), scoreClass(x.quant_health_score))}${factor(\"技術\", n(x.technical_score,2), scoreClass(x.technical_score))}${factor(\"估值\", n(x.valuation_score,2), scoreClass(x.valuation_score))}</div><div class=\"q-zone-grid\"><div class=\"q-zone\"><div class=\"q-zone-k\">月支撐</div><div class=\"q-zone-v\">${zone(x,\"support\")}</div></div><div class=\"q-zone\"><div class=\"q-zone-k\">月壓力</div><div class=\"q-zone-v\">${zone(x,\"resistance\")}</div></div></div><div class=\"q-position\"><b>月線：</b>${esc(position)}${reason ? `<br><span style=\"color:#94a3b8\">${esc(reason)}</span>` : \"\"}</div><div class=\"q-mobile-foot\">${esc(x.source || \"N/A\")} · ${esc(x.updated_at || \"N/A\")}</div></article>`;\n    }).join(\"\");\n    p.innerHTML = `<div class=\"qmi-head\"><div><div class=\"qmi-title\">量化因子總覽</div><div class=\"qmi-sub\">趨勢＝均線位置與斜率；動能＝1M/3M/6M/12M 報酬。風險、健康度與月線支撐/壓力獨立呈現；籌碼只作台股附加資料。</div></div><div class=\"qmi-meta\">持倉數=${list.length}<br>最新=${esc(latest)}</div></div><div class=\"qwrap\"><table><thead><tr><th>代號</th><th>Beta</th><th>趨勢</th><th>動能</th><th>風險</th><th>技術</th><th>估值</th><th>健康度</th><th>月支撐</th><th>月壓力</th><th>月線位置</th><th>綜合訊號</th><th>品質</th><th>來源</th><th>更新</th></tr></thead><tbody>${rows}</tbody></table></div><div class=\"qcards\">${cards}</div>`;\n'''

js = replace_once(js, old_rows, new_rows, 'mobile quant card renderer')

